// MASUKKAN GROQ API KEY ANDA DI BARIS INI (dipakai STT + AI Agent + TTS):
const GROQ_API_KEY = 'MASUKKAN_GROQ_API_KEY_ANDA_DISINI';

// Pastikan binary audio bernama 'data' berekstensi .wav agar diterima Groq Whisper
const item = $input.first();
const binKeys = item.binary ? Object.keys(item.binary) : [];

if (binKeys.length === 0) {
  throw new Error('Tidak ada file audio WAV biner yang diterima di Webhook!');
}

const firstKey = binKeys[0];
const binObj = item.binary[firstKey];
binObj.fileName = 'voice.wav';
binObj.mimeType = 'audio/wav';

if (firstKey !== 'data') {
  item.binary.data = binObj;
  delete item.binary[firstKey];
}

const query = (item.json && item.json.query) ? item.json.query : {};
const temp = Number(parseFloat(query.temp ?? 28.0).toFixed(1));
const hum = Number(parseFloat(query.hum ?? 65.0).toFixed(1));
const pir = Number(query.pir ?? 0) === 1 ? 1 : 0;

item.json = {
  ...item.json,
  groqApiKey: GROQ_API_KEY.replace(/^Bearer\s+/i, '').trim(),
  temp,
  hum,
  pir,
  receivedAt: new Date().toISOString()
};

return item;

const prep = $('Prepare WAV Binary & Sensor').first().json || {};
const stt = $input.first().json || {};

const transcript = String(stt.text || '').trim();
const sttError = stt.error ? (stt.error.message || JSON.stringify(stt.error)) : '';
const temp = Number(prep.temp ?? 28.0);
const hum = Number(prep.hum ?? 65.0);
const pir = Number(prep.pir ?? 0) === 1 ? 1 : 0;
const pirLabel = pir === 1 ? 'Gerakan Terdeteksi' : 'Aman Standby';

return {
  json: {
    groqApiKey: prep.groqApiKey || '',
    transcript: transcript || '(Suara tidak terdengar jelas)',
    sttEmpty: transcript.length < 2,
    sttError,
    temp,
    hum,
    pir,
    pirLabel,
    receivedAt: prep.receivedAt || new Date().toISOString()
  }
};

const ctx = $('Susun Konteks AI Agent & Sensor').first().json;
const res = $input.first().json || {};

let rawReply = '';
let llmError = '';

if (res && res.choices && res.choices.length > 0) {
  rawReply = String(res.choices[0].message.content || '').replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
} else {
  if (res && res.error) {
    llmError = res.error.message || 'Groq API error';
  }
  rawReply = ctx.sttEmpty
    ? 'Hello! I did not hear clearly, please speak closer to my microphone. [FACE:LOOK_AROUND]'
    : 'Hello! I am Vortex X, ready to serve you! [CMD:WAVE] [FACE:HAPPY]';
}

let cmd = '';
let face = '';

const cmdMatch = rawReply.match(/\[CMD:([A-Z_]+)\]/i);
if (cmdMatch) {
  cmd = cmdMatch[1].toUpperCase();
}

const faceMatch = rawReply.match(/\[FACE:([A-Z_]+)\]/i);
if (faceMatch) {
  face = faceMatch[1].toUpperCase();
}

let cleanText = rawReply
  .replace(/\[CMD:[A-Z_]+\]/gi, '')
  .replace(/\[FACE:[A-Z_]+\]/gi, '')
  .replace(/[*_`#]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

if (!cleanText) cleanText = 'Ready for your command.';
if (cleanText.length > 185) {
  cleanText = cleanText.slice(0, 182) + '...';
}

let eventCategory = 'VOICE_CHAT';
if (ctx.pir === 1) {
  eventCategory = 'VOICE_PIR_ALERT';
} else if (ctx.temp >= 35.0) {
  eventCategory = 'VOICE_OVERHEAT';
} else if (cmd || face) {
  eventCategory = 'VOICE_ACTION';
}

return {
  json: {
    groqApiKey: ctx.groqApiKey || '',
    transcript: ctx.transcript,
    sttEmpty: ctx.sttEmpty,
    sttError: ctx.sttError,
    llmError,
    cleanText,
    cmd,
    face,
    headerText: cleanText.replace(/[^\x20-\x7E]/g, '').slice(0, 90),
    temp: ctx.temp,
    hum: ctx.hum,
    pir: ctx.pir,
    pirLabel: ctx.pirLabel,
    eventCategory,
    incidentId: 'VX-V' + Math.floor(10000 + Math.random() * 90000),
    receivedAt: ctx.receivedAt
  }
};

// Pastikan selalu ada file WAV 44-byte header standar yang bersih untuk ESP32 MAX98357A
const item = $input.first();
const meta = $('Extract AI Reply & Klasifikasi').first().json;

const hasBinary = Boolean(item && item.binary && item.binary.data && item.binary.data.data);
let ttsError = '';
let ttsFallbackUsed = false;

if (hasBinary) {
  try {
    const rawData = await this.helpers.getBinaryDataBuffer(0, 'data');
    const rawBuf = Buffer.from(rawData);
    if (rawBuf && rawBuf.length > 44 && rawBuf.toString('ascii', 0, 4) === 'RIFF' && rawBuf.toString('ascii', 8, 4) === 'WAVE') {
      let sr = 24000;
      let ch = 1;
      let bps = 16;
      let pcmSlice = null;
      let off = 12;
      while (off + 8 <= rawBuf.length) {
        const id = rawBuf.toString('ascii', off, off + 4);
        const sz = rawBuf.readUInt32LE(off + 4);
        if (id === 'fmt ' && off + 8 + 16 <= rawBuf.length) {
          ch  = rawBuf.readUInt16LE(off + 10);
          sr  = rawBuf.readUInt32LE(off + 12);
          bps = rawBuf.readUInt16LE(off + 22);
        }
        if (id === 'data') {
          const dataStart = off + 8;
          const dataEnd = (sz === 0xFFFFFFFF || sz === 0 || dataStart + sz > rawBuf.length) ? rawBuf.length : (dataStart + sz);
          pcmSlice = rawBuf.subarray(dataStart, dataEnd);
          break;
        }
        if (sz === 0xFFFFFFFF || sz === 0) break;
        off += 8 + sz + (sz % 2);
      }
      if (pcmSlice && pcmSlice.length > 0) {
        // Trim leading silence (>20ms nol murni) agar speaker langsung berbunyi
        let trimOff = 0;
        while (trimOff + 2 <= pcmSlice.length && Math.abs(pcmSlice.readInt16LE(trimOff)) < 8 && trimOff < sr * 2 * 0.25) {
          trimOff += 2;
        }
        if (trimOff > 64) pcmSlice = pcmSlice.subarray(trimOff);
        const pcmBytes = pcmSlice.length - (pcmSlice.length % 2);
        const cleanWav = Buffer.alloc(44 + pcmBytes);
        const byteRate = sr * ch * (bps / 8);
        const blockAlign = ch * (bps / 8);
        cleanWav.write('RIFF', 0, 'ascii');
        cleanWav.writeUInt32LE(36 + pcmBytes, 4);
        cleanWav.write('WAVE', 8, 'ascii');
        cleanWav.write('fmt ', 12, 'ascii');
        cleanWav.writeUInt32LE(16, 16);
        cleanWav.writeUInt16LE(1, 20);
        cleanWav.writeUInt16LE(ch, 22);
        cleanWav.writeUInt32LE(sr, 24);
        cleanWav.writeUInt32LE(byteRate, 28);
        cleanWav.writeUInt16LE(blockAlign, 32);
        cleanWav.writeUInt16LE(bps, 34);
        cleanWav.write('data', 36, 'ascii');
        cleanWav.writeUInt32LE(pcmBytes, 40);
        pcmSlice.copy(cleanWav, 44, 0, pcmBytes);
        const cleanBin = await this.helpers.prepareBinaryData(cleanWav, 'reply.wav', 'audio/wav');
        return [{
          json: {
            ttsFallbackUsed: false,
            ttsError: '',
            cmd: meta.cmd,
            face: meta.face,
            headerText: meta.headerText,
            wavBytes: cleanWav.length
          },
          binary: { data: cleanBin }
        }];
      }
    }
  } catch (e) {
    // Jika gagal rapikan header, tetap teruskan biner apa adanya
  }
  item.binary.data.fileName = 'reply.wav';
  item.binary.data.mimeType = 'audio/wav';
  return [{
    json: {
      ttsFallbackUsed: false,
      ttsError: '',
      cmd: meta.cmd,
      face: meta.face,
      headerText: meta.headerText
    },
    binary: item.binary
  }];
}

ttsFallbackUsed = true;
ttsError = (item && item.json && item.json.error)
  ? String(item.json.error.message || item.json.message || 'TTS Groq belum aktif (Accept Terms Orpheus)')
  : 'TTS Groq tidak mengembalikan audio WAV';

const sr = 16000;
const numSamples = Math.floor(sr * 0.45);
const pcmBytes = numSamples * 2;
const wavBuf = Buffer.alloc(44 + pcmBytes);

wavBuf.write('RIFF', 0, 'ascii');
wavBuf.writeUInt32LE(36 + pcmBytes, 4);
wavBuf.write('WAVE', 8, 'ascii');
wavBuf.write('fmt ', 12, 'ascii');
wavBuf.writeUInt32LE(16, 16);
wavBuf.writeUInt16LE(1, 20);
wavBuf.writeUInt16LE(1, 22);
wavBuf.writeUInt32LE(sr, 24);
wavBuf.writeUInt32LE(sr * 2, 28);
wavBuf.writeUInt16LE(2, 32);
wavBuf.writeUInt16LE(16, 34);
wavBuf.write('data', 36, 'ascii');
wavBuf.writeUInt32LE(pcmBytes, 40);

for (let i = 0; i < numSamples; i++) {
  const freq = i < numSamples / 2 ? 660 : 880;
  const t = i / sr;
  const env = Math.min(1, Math.min(i, numSamples - i) / 400);
  const sample = Math.round(Math.sin(2 * Math.PI * freq * t) * 14000 * env);
  wavBuf.writeInt16LE(sample, 44 + i * 2);
}

const binData = await this.helpers.prepareBinaryData(wavBuf, 'reply.wav', 'audio/wav');
return [{
  json: {
    ttsFallbackUsed,
    ttsError,
    cmd: meta.cmd,
    face: meta.face,
    headerText: meta.headerText,
    wavBytes: wavBuf.length
  },
  binary: { data: binData }
}];

// Setelah audio dikirim secepatnya ke Speaker ESP32, susun konteks untuk Telegram Bot
const { groqApiKey, ...data } = $('Extract AI Reply & Klasifikasi').first().json;
