const item = $input.first().json;
const staticData = $getWorkflowStaticData('global');

const now = Date.now();
const lastAlertTime = staticData.lastAlertTime || 0;
const lastPIRAlert = staticData.lastPIRAlert || 0;

let eventCategory = 'ROUTINE_TELEMETRY';
let threatLevel = 'NORMAL';

if (item.pirState === 1 || item.eventType === 'PIR_INTRUSION') {
  eventCategory = 'PIR_INTRUSION';
  threatLevel = 'CRITICAL';
} else if (item.temperature >= 35.0) {
  eventCategory = 'OVERHEAT_WARNING';
  threatLevel = 'WARNING';
} else if (item.aiScore < 0.65) {
  eventCategory = 'AI_ANOMALY';
  threatLevel = 'WARNING';
} else if (item.customMsg && item.eventType !== 'ROUTINE_TELEMETRY') {
  eventCategory = 'SYSTEM_EVENT';
  threatLevel = 'INFO';
}

let allowNotification = true;
if (eventCategory === 'PIR_INTRUSION') {
  if (now - lastPIRAlert < 15000) {
    allowNotification = false;
  } else {
    staticData.lastPIRAlert = now;
  }
} else if (threatLevel === 'NORMAL' && (now - lastAlertTime < 25000)) {
  allowNotification = false;
}
if (allowNotification) {
  staticData.lastAlertTime = now;
}

const healthPct = (item.aiScore * 100).toFixed(0);
const groqPrompt = `Telemetri Robot ${item.device}:
- Event: ${eventCategory} (Level: ${threatLevel})
- Sensor PIR: ${item.pirState === 1 ? 'AKTIF DETEKSI GERAKAN' : 'AMAN STANDBY'}
